<template><div class="space-y-6"><section class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-6"><article v-for="kpi in kpis" :key="kpi.label" class="premium-card group rounded-2xl border border-slate-200/80 bg-white/90 p-4 shadow-card dark:border-slate-800/80 dark:bg-slate-900/80"><div class="flex items-start justify-between gap-3"><span class="grid h-10 w-10 place-items-center rounded-xl text-xs font-bold" :class="kpi.iconTone"><i class="fa-solid" :class="kpi.icon"></i></span><span class="rounded-md bg-slate-100 dark:bg-slate-800 px-2 py-0.5 text-[10px] font-bold" :class="kpi.deltaTone">{{ kpi.delta }}</span></div><p class="mt-3.5 text-[11px] font-bold uppercase tracking-wider text-slate-400 dark:text-slate-500">{{ kpi.label }}</p><p class="font-head font-mono mt-1 text-xl sm:text-2xl font-800 text-slate-900 dark:text-white">{{ kpi.value }}</p><div class="mt-3 h-1.5 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800"><div class="h-full rounded-full bg-brand transition-all duration-500" :style="{width:kpi.progress+'%'}"></div></div></article></section><section class="grid gap-6 2xl:grid-cols-[minmax(0,1.25fr)_minmax(330px,.75fr)]"><article class="panel overflow-hidden rounded-2xl border border-slate-200/80 bg-white/90 shadow-card dark:border-slate-800/80 dark:bg-slate-900/80"><header class="flex flex-col gap-3 border-b border-slate-100 p-5 dark:border-slate-800 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="font-head font-800 text-base tracking-tight text-slate-900 dark:text-white">Open activity</h2><p class="mt-0.5 text-xs text-slate-400">Every number opens the records behind it.</p></div><RouterLink to="/procurement/queue" class="text-xs font-bold text-brand hover:underline">View requests <i class="fa-solid fa-arrow-right ml-1"></i></RouterLink></header><div class="grid divide-y divide-slate-100 dark:divide-slate-800 sm:grid-cols-4 sm:divide-x sm:divide-y-0"><RouterLink v-for="step in pipeline" :key="step.label" :to="step.to" class="group p-5 transition hover:bg-slate-50 dark:hover:bg-slate-800/40"><div class="flex items-center justify-between"><span class="grid h-9 w-9 place-items-center rounded-xl bg-slate-100 text-slate-500 transition group-hover:bg-brand group-hover:text-white dark:bg-slate-800 dark:text-slate-400"><i class="fa-solid text-xs" :class="step.icon"></i></span><span class="font-head font-mono text-2xl font-800 text-slate-900 dark:text-white">{{ step.value }}</span></div><b class="font-head mt-4 block text-xs font-bold text-slate-800 dark:text-slate-200">{{ step.label }}</b><p class="mt-1 text-[11px] leading-relaxed text-slate-400">{{ step.note }}</p></RouterLink></div><div class="border-t border-slate-100 p-5 dark:border-slate-800"><div class="mb-4 flex items-center justify-between"><h3 class="font-head font-bold text-xs uppercase tracking-wider text-slate-400">Spend & savings pulse</h3><span class="text-[10px] font-bold uppercase tracking-wider text-slate-400">Last 6 months</span></div><div class="flex h-44 items-end gap-3 sm:gap-5 pt-4"><div v-for="point in analytics.monthly" :key="point.month" class="group flex h-full min-w-0 flex-1 flex-col justify-end"><div class="relative flex flex-1 items-end justify-center gap-1.5"><div class="w-2/5 rounded-t-lg bg-slate-200 transition group-hover:bg-slate-300 dark:bg-slate-700 dark:group-hover:bg-slate-600" :style="{height:bar(point.spend,150000)}" :title="store.money(point.spend)"></div><div class="w-2/5 rounded-t-lg bg-brand transition shadow-soft" :style="{height:bar(point.savings,15000)}" :title="store.money(point.savings)"></div></div><span class="mt-2 text-center text-[10px] font-bold text-slate-400">{{ point.month }}</span></div></div><div class="mt-4 flex gap-5 text-[11px] font-medium text-slate-500 dark:text-slate-400"><span class="flex items-center gap-1.5"><i class="inline-block h-2 w-2 rounded-full bg-slate-300 dark:bg-slate-600"></i>Spend</span><span class="flex items-center gap-1.5"><i class="inline-block h-2 w-2 rounded-full bg-brand"></i>Savings</span></div></div></article><aside class="space-y-6"><article class="panel overflow-hidden rounded-2xl border border-slate-200/80 bg-white/90 shadow-card dark:border-slate-800/80 dark:bg-slate-900/80"><header class="flex items-center justify-between border-b border-slate-100 p-4 dark:border-slate-800"><div><h2 class="font-head font-800 text-sm tracking-tight text-slate-900 dark:text-white">Needs action</h2><p class="mt-0.5 text-[11px] text-slate-400">Issues and decisions assigned to you</p></div><span class="rounded-full bg-rose-50 px-2.5 py-0.5 text-xs font-bold text-rose-600 dark:bg-rose-950/50 dark:text-rose-400">{{ workQueue.length }}</span></header><div class="divide-y divide-slate-100 dark:divide-slate-800"><RouterLink v-for="item in workQueue" :key="item.id" :to="item.to" class="flex gap-3.5 p-4 transition hover:bg-slate-50 dark:hover:bg-slate-800/40"><span class="mt-0.5 grid h-9 w-9 flex-none place-items-center rounded-xl text-xs" :class="item.tone"><i class="fa-solid" :class="item.icon"></i></span><span class="min-w-0 flex-1"><span class="flex items-center justify-between gap-2"><b class="truncate text-xs font-bold text-slate-800 dark:text-slate-200">{{ item.title }}</b><small class="flex-none text-[10px] font-bold text-slate-400">{{ item.when }}</small></span><span class="mt-0.5 block text-xs text-slate-500 dark:text-slate-400">{{ item.detail }}</span><span class="mt-2 inline-flex items-center text-[10px] font-bold text-brand hover:underline">{{ item.action }} <i class="fa-solid fa-chevron-right ml-1 text-[8px]"></i></span></span></RouterLink></div></article><article class="panel p-5 rounded-2xl border border-slate-200/80 bg-white/90 shadow-card dark:border-slate-800/80 dark:bg-slate-900/80"><div class="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800"><h2 class="font-head font-800 text-sm tracking-tight text-slate-900 dark:text-white">Top Suppliers</h2><RouterLink to="/procurement/intelligence" class="text-xs font-bold text-brand hover:underline">Performance</RouterLink></div><div class="mt-4 space-y-2"><RouterLink
              v-for="(supplier,index) in topSuppliers"
              :key="supplier.id"
              :to="`/suppliers?supplier=${supplier.id}`"
              class="grid grid-cols-[1.8rem_minmax(0,1fr)_2.4rem] items-center gap-2 p-1.5 rounded-xl transition hover:bg-slate-50 dark:hover:bg-slate-800/50"
            ><span class="grid h-7 w-7 place-items-center rounded-lg bg-slate-100 text-xs font-bold text-slate-600 dark:bg-slate-800 dark:text-slate-300">{{ index+1 }}</span><div class="min-w-0"><div class="flex items-center justify-between gap-2"><b class="truncate text-xs font-bold text-slate-800 hover:text-brand dark:text-slate-200">{{ supplier.name }}</b><span class="text-[10px] text-slate-400 font-mono">{{ supplier.onTime }}% on time</span></div><div class="mt-1.5 h-1.5 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800"><div class="h-full rounded-full" :class="supplier.risk>35?'bg-amber-400':'bg-emerald-500'" :style="{width:supplier.score+'%'}"></div></div></div><b class="text-right font-mono text-xs font-bold text-slate-800 dark:text-slate-200">{{ supplier.score }}</b></RouterLink></div></article></aside></section><section><article class="panel p-6 rounded-2xl border border-slate-200/80 bg-white/90 shadow-card dark:border-slate-800/80 dark:bg-slate-900/80"><div class="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800"><div><h2 class="font-head font-800 text-base tracking-tight text-slate-900 dark:text-white">Recent activity</h2><p class="mt-0.5 text-xs text-slate-400">Requests, offers, orders and invoice checks in one history.</p></div><RouterLink to="/procurement/intelligence" class="text-xs font-bold text-brand hover:underline">View insights</RouterLink></div><div class="mt-5 grid gap-3 md:grid-cols-2"><div v-for="event in store.state.procurementAudit.slice(0,6)" :key="event.id" class="flex gap-3.5 rounded-xl border border-slate-100 bg-slate-50/60 p-3.5 dark:border-slate-800 dark:bg-slate-800/30"><span class="mt-1 h-2.5 w-2.5 flex-none rounded-full" :class="event.level==='warning'?'bg-amber-400':event.level==='danger'?'bg-rose-500':event.level==='success'?'bg-emerald-400':'bg-sky-400'"></span><div class="min-w-0 flex-1"><div class="flex items-center justify-between gap-2"><b class="truncate text-xs font-bold text-slate-800 dark:text-slate-200">{{ event.action }}</b><RouterLink
                  v-if="auditLink(event.objectId)"
                  :to="auditLink(event.objectId)"
                  class="rounded-md bg-brand-50 px-2 py-0.5 text-[9px] font-mono font-bold text-brand hover:underline dark:bg-brand/20"
                >{{ event.objectId }}</RouterLink><span v-else class="rounded-md bg-slate-200/70 px-1.5 py-0.5 text-[9px] font-mono font-bold text-slate-600 dark:bg-slate-700 dark:text-slate-300">{{ event.objectId }}</span></div><p class="mt-1 text-xs text-slate-500 dark:text-slate-400">{{ event.detail }}</p><p class="mt-1 text-[10px] text-slate-400">{{ event.actor }} · {{ store.date(event.at) }}</p></div></div></div></article></section></div></template>
<script>
const {inject,computed}=Vue;
export default {setup(){const store=inject('store'),analytics=store.state.procurementAnalytics;
const activeRequests=computed(()=>store.state.purchaseRequests.filter(item=>!['Closed','Rejected'].includes(item.status)).length);
const activeEvents=computed(()=>store.state.sourcingEvents.filter(item=>!['Closed','Awarded'].includes(item.status)).length);
const openOrders=computed(()=>store.state.purchaseOrders.filter(item=>!['Matched','Closed'].includes(item.status)).length);
const exceptionCount=computed(()=>store.state.purchaseOrders.reduce((sum,item)=>sum+(item.exceptions||[]).filter(exception=>exception.status!=='Resolved').length,0));
const kpis=computed(()=>[
{label:'Addressable spend',value:store.money(analytics.kpis.addressableSpend),delta:'+6.1% coverage',progress:87,icon:'fa-wallet',iconTone:'bg-violet-50 text-violet-600 dark:bg-violet-500/10 dark:text-violet-300',deltaTone:'text-violet-500'},
{label:'Realized savings',value:store.money(analytics.kpis.realizedSavings),delta:`${analytics.kpis.savingsRate}% rate`,progress:74,icon:'fa-piggy-bank',iconTone:'bg-emerald-50 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-300',deltaTone:'text-emerald-500'},
{label:'Open requests',value:activeRequests.value,delta:'1 due today',progress:58,icon:'fa-inbox',iconTone:'bg-sky-50 text-sky-600 dark:bg-sky-500/10 dark:text-sky-300',deltaTone:'text-amber-500'},
{label:'Open quotes',value:activeEvents.value,delta:'2 decisions',progress:66,icon:'fa-file-signature',iconTone:'bg-brand-50 text-brand',deltaTone:'text-brand'},
{label:'Orders in flight',value:openOrders.value,delta:'1 partial',progress:62,icon:'fa-truck-fast',iconTone:'bg-amber-50 text-amber-600 dark:bg-amber-500/10 dark:text-amber-300',deltaTone:'text-amber-500'},
{label:'Open issues',value:exceptionCount.value,delta:'1 high',progress:24,icon:'fa-triangle-exclamation',iconTone:'bg-rose-50 text-rose-600 dark:bg-rose-500/10 dark:text-rose-300',deltaTone:'text-rose-500'}]);
const pipeline=computed(()=>[
{label:'Requests',value:activeRequests.value,note:'Intake and approvals waiting',icon:'fa-inbox',to:'/procurement/queue'},
{label:'Quotes',value:activeEvents.value,note:'Invitations, offers and comparison',icon:'fa-file-signature',to:'/procurement/sourcing'},
{label:'Orders',value:openOrders.value,note:'Commitment, receipt and follow-up',icon:'fa-cart-shopping',to:'/procurement/execution'},
{label:'Invoice checks',value:exceptionCount.value,note:'Issues that still need review',icon:'fa-link',to:'/procurement/execution'}]);
const workQueue=computed(()=>[
...store.state.purchaseRequests.filter(item=>item.status==='Pending approval').map(item=>({id:item.id,title:item.title,detail:`${store.money(item.amount,item.currency)} · ${item.department}`,when:item.dueDate?store.date(item.dueDate):'Today',action:'Review decision',to:`/procurement/queue?request=${item.id}`,icon:'fa-stamp',tone:'bg-amber-50 text-amber-600 dark:bg-amber-500/10'})),
...store.state.purchaseOrders.flatMap(order=>(order.exceptions||[]).filter(item=>item.status!=='Resolved').map(item=>({id:item.id,title:item.type,detail:`${order.id} · ${item.detail}`,when:item.severity,action:'Resolve issue',to:`/procurement/execution?order=${order.id}`,icon:'fa-triangle-exclamation',tone:'bg-rose-50 text-rose-600 dark:bg-rose-500/10'}))),
...store.state.sourcingEvents.filter(item=>item.status==='Comparing').map(item=>({id:item.id,title:'Supplier choice ready',detail:`${item.id} · ${(item.quotes||[]).length} offers`,when:'Now',action:'Compare offers',to:`/procurement/sourcing?event=${item.id}`,icon:'fa-scale-balanced',tone:'bg-violet-50 text-violet-600 dark:bg-violet-500/10'}))
].slice(0,5));
const topSuppliers=computed(()=>[...store.state.suppliers].sort((a,b)=>b.score-a.score).slice(0,4));
const bar=(value,max)=>`${Math.max(6,Math.round(Number(value||0)/max*100))}%`;
const auditLink=(id)=>{
if(!id)return null;
if(id.startsWith('PR-'))return `/procurement/queue?request=${id}`;
if(id.startsWith('RFQ-')||id.startsWith('RFP-')||id.startsWith('RFI-'))return `/procurement/sourcing?event=${id}`;
if(id.startsWith('AUC-'))return `/procurement/auction?auction=${id}`;
if(id.startsWith('PO-'))return `/procurement/execution?order=${id}`;
if(id.startsWith('inv-')||id.startsWith('FAC-'))return `/invoices/${id}`;
return null;
};
return{store,analytics,kpis,pipeline,workQueue,topSuppliers,bar,auditLink};}}
</script>